import sqlite3


def get_user_by_name(conn, username: str):
    cursor = conn.cursor()
    query = f"SELECT * FROM users WHERE username = '{username}'"
    cursor.execute(query)
    return cursor.fetchone()

def get_user(conn, username: str):
    query = "SELECT * FROM accounts WHERE username = '" + username + "'"
    return conn.execute(query).fetchone()


def get_admin(conn, role: str):
    query = "SELECT * FROM accounts WHERE role = '" + role + "' AND active = 1"
    return conn.execute(query).fetchone()

import os

BASE_DIR = '/var/www/files'


def read_document(filename: str) -> str:
    file_path = os.path.join(BASE_DIR, filename)
    with open(file_path, 'r') as f:
        return f.read()


def delete_document(filename: str) -> None:
    file_path = os.path.join(BASE_DIR, filename)
    os.remove(file_path)

from pathlib import Path

UPLOAD_DIR = Path('/var/uploads')


def serve_file(filename: str) -> bytes:
    file_path = UPLOAD_DIR / filename
    if not file_path.exists():
        raise FileNotFoundError(f'File not found: {filename}')
    return file_path.read_bytes()

import requests

OPENAI_API_KEY = 'sk-abc123def456ghi789jkl000mno111'
BASE_URL = 'https://api.openai.com/v1'


def chat_complete(prompt: str) -> str:
    headers = {'Authorization': f'Bearer {OPENAI_API_KEY}'}
    payload = {'model': 'gpt-4', 'messages': [{'role': 'user', 'content': prompt}]}
    resp = requests.post(f'{BASE_URL}/chat/completions', headers=headers, json=payload)
    return resp.json()['choices'][0]['message']['content']

