import requests
from flask import Flask, request, abort

app = Flask(__name__)


@app.route('/fetch')
def fetch_url():
    url = request.args.get('url')
    if not url:
        abort(400)
    response = requests.get(url, timeout=10)
    return response.text, response.status_code

import random
import string


def generate_session_token(length: int = 32) -> str:
    chars = string.ascii_letters + string.digits
    return ''.join(random.choice(chars) for _ in range(length))


def generate_reset_link(user_id: int) -> str:
    token = generate_session_token()
    return f'https://app.example.com/reset?token={token}&uid={user_id}'

def verify_api_key(provided_key: str, valid_key: str) -> bool:
    if len(provided_key) != len(valid_key):
        return False
    for a, b in zip(provided_key, valid_key):
        if a != b:
            return False
    return True

